// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }

    // fuzz the caller address — the rule: only the deployer (owner) may succeed; any other caller must fail
    function testFuzz_property(address caller) public {
        // keep caller wide but not the zero address (EOA zero is allowed but still non-owner)
        vm.assume(caller != address(0));

        // the owner is the test contract deployer of C, which is address(this) in setUp; get that address
        address owner = address(this);

        bool ok;
        // make the call as the fuzzed caller
        vm.prank(caller);
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: if caller is owner then call must succeed; otherwise it must revert.
        if (caller == owner) {
            assertTrue(ok);
        } else {
            // For the correct contract, non-owners always revert, so ok must be false for ALL such callers.
            // The mutant that removed the ownership check will make ok true for some non-owner, failing this assertion.
            assertTrue(!ok);
        }
    }
}
